use nova_event_bus::Event; use nova_state::{transition,State}; use nova_types::StateRoot;
#[derive(Clone,Debug,Eq,PartialEq)] pub struct ReplayResult { pub applied:usize,pub root:StateRoot,pub expected:Option<StateRoot> }
#[derive(Debug,Clone,Eq,PartialEq)] pub enum ReplayError { Event(String), Transition(String), RootMismatch{expected:StateRoot,actual:StateRoot} }
pub fn replay(events:&[Event], expected:Option<StateRoot>)->Result<ReplayResult,ReplayError>{let mut s=State::default();let mut last=None;for e in events{e.validate().map_err(|x|ReplayError::Event(format!("{x:?}")))?;if last.map(|x|x>=e.id).unwrap_or(false){return Err(ReplayError::Event("non-monotonic event id".into()))}if e.parent!=last{return Err(ReplayError::Event("invalid parent".into()))}s=transition(&s,e).map_err(|x|ReplayError::Transition(format!("{x:?}")))?.next;last=Some(e.id);}let root=s.root();if let Some(exp)=expected{if exp!=root{return Err(ReplayError::RootMismatch{expected:exp,actual:root})}}Ok(ReplayResult{applied:events.len(),root,expected})}
#[cfg(test)] mod tests{use super::*;use nova_types::{EventId,LogicalTime,Provenance};#[test]fn same_history_same_root(){let p=Provenance{origin:"t".into(),trace_id:"x".into()};let es=vec![Event::increment(EventId(1),LogicalTime(1),None,2,p.clone()),Event::increment(EventId(2),LogicalTime(2),Some(EventId(1)),3,p)];assert_eq!(replay(&es,None).unwrap().root,replay(&es,None).unwrap().root);} }
